// Bundles knowledge/*.md into functions/api/_knowledge.js. Run after editing knowledge docs.
import fs from "fs";
const dir = new URL("../knowledge/", import.meta.url);
const docs = fs.readdirSync(dir).filter((f) => f.endsWith(".md")).sort()
  .map((f) => ({ f, t: fs.readFileSync(new URL(f, dir), "utf8").replace(/<!--[\s\S]*?-->/g, "").split("\n").filter((l) => !/TODO/.test(l)).join("\n").trim() }));
fs.writeFileSync(new URL("../functions/api/_knowledge.js", import.meta.url),
  "// GENERATED by scripts/build-knowledge.mjs. Do not edit.\nexport const KNOWLEDGE = " + JSON.stringify(docs.map((d) => `### ${d.f}\n${d.t}`).join("\n\n")) + ";\n");
